mapper.select:
SELECT a.OperatorID AS operatorId, a.ShiftID AS shiftId, a.TeamID AS teamId, IFNULL(SUM(CASE WHEN DealStatus&14=6 THEN CarNum ELSE 0 END),0) as officialIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=8 THEN CarNum ELSE 0 END),0) as militaryIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=12 THEN CarNum ELSE 0 END),0) as freeIcCardCount, IFNULL(SUM(CASE WHEN (DealStatus&14!=14 AND DealStatus&14!=2 AND DealStatus&0xE00000!=0x200000 AND DealStatus&0x1000000=0 AND DealStatus&32!=32 AND CardType=0) OR (CardType=26 AND DealStatus&32!=32) THEN CardNum ELSE 0 END),0) as dueIcCardCount, IFNULL(CAST(SUM(CASE WHEN PayType=0 THEN TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) as douTotalToll, IFNULL(CAST(SUM(CASE WHEN DealStatus&14=4 THEN TotalArrearage ELSE 0 END)/100 AS DECIMAL(10,2)), 0) as arrearsAmount, IFNULL(SUM(CASE WHEN DealStatus&14=4 THEN CarNum ELSE 0 END),0) as arrearsTrips, IFNULL(CAST(SUM(CASE WHEN PayType=16 THEN TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) mobilePaymentAmount, IFNULL(CAST(SUM(CASE WHEN PayType=2 THEN TotalToll ELSE 0 END) /100 as DECIMAL(10,2)), 0) as ePaymentAmount FROM `tbstatexit` a
AND StationID in
#{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
AND CancelFlag = 0 AND RecordType&1 =1 AND substring(LaneID,-3,1) = 1 AND substring(LaneID,-4,1) = 0
GROUP BY OperatorID ORDER BY OperatorID ASC

SELECT a.OperatorID AS operatorId, a.ShiftID AS shiftId, a.TeamID AS teamId, IFNULL(SUM(CASE WHEN DealStatus&14=6 THEN CarNum ELSE 0 END),0) as officialIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=8 THEN CarNum ELSE 0 END),0) as militaryIcCardCount, IFNULL(SUM(CASE WHEN DealStatus&14=12 THEN CarNum ELSE 0 END),0) as freeIcCardCount, IFNULL(SUM(CASE WHEN (DealStatus&14!=14 AND DealStatus&14!=2 AND DealStatus&0xE00000!=0x200000 AND DealStatus&0x1000000=0 AND DealStatus&32!=32 AND CardType=0) OR (CardType=26 AND DealStatus&32!=32) THEN CardNum ELSE 0 END),0) as dueIcCardCount, IFNULL(CAST(SUM(CASE WHEN PayType=0 THEN TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) AS douTotalToll, IFNULL(CAST(SUM(CASE WHEN DealStatus&14=4 THEN TotalArrearage ELSE 0 END)/100 AS DECIMAL(10,2)), 0) AS arrearsAmount, IFNULL(SUM(CASE WHEN DealStatus&14=4 THEN CarNum ELSE 0 END),0) AS arrearsTrips, IFNULL(CAST(SUM(CASE WHEN PayType=16 THEN TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) AS mobilePaymentAmount, IFNULL(CAST(SUM(CASE WHEN PayType=2 THEN TotalToll ELSE 0 END) /100 as DECIMAL(10,2)), 0) as ePaymentAmount FROM `tbstatexit` a
AND StationID in
#{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
AND CancelFlag = 0 AND RecordType &1 =1
GROUP BY OperatorID ORDER BY ShiftID ASC, OperatorID ASC

SELECT a.OperatorID AS operatorId, a.ShiftID AS shiftId, IFNULL(CAST(SUM(AddedToll)/100 as DECIMAL(10,2)), 0) as addedToll, IFNULL(CAST(SUM(HandToll)/100 as DECIMAL(10,2)), 0) as handToll, IFNUll(SUM(HandInCNum), 0) AS handInCNum, IFNULL(SUM(HandOutCNum), 0) AS handOutCNum FROM `tbsh` a
AND a.CancelFlag = 0 AND a.StationID in
#{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
GROUP BY OperatorID

SELECT IFNULL(CAST(SUM(a.AddedToll)/100 as DECIMAL(10,2)) ,0) as addedToll, IFNULL(CAST(SUM(a.HandToll)/100 as DECIMAL(10,2)), 0) as handToll, IFNULL(SUM(a.HandInCNum), 0) AS handInCNum, IFNULL(SUM(a.HandOutCNum), 0) AS handOutCNum, a.StaDate AS staDate, LEFT(a.StaDate, 6) AS monthDate, a.StationID AS stationId, a.OperatorID AS operatorId FROM
SELECT * FROM ${tableName}
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
GROUP BY OperatorID

SELECT IFNULL(CAST(SUM(a.AddedToll)/100 as DECIMAL(10,2)) ,0) as addedToll, IFNULL(CAST(SUM(a.HandToll)/100 as DECIMAL(10,2)), 0) as handToll, IFNULL(SUM(a.HandInCNum), 0) AS handInCNum, IFNULL(SUM(a.HandOutCNum), 0) AS handOutCNum, a.StaDate AS staDate, LEFT(a.StaDate, 6) AS monthDate, a.StationID AS stationId, a.OperatorID AS operatorId FROM
SELECT * FROM ${tableName}
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
GROUP BY OperatorID

SELECT a.StaDate AS staDate, LEFT(a.StaDate, 6) AS monthDate, a.OperatorID AS operatorId, a.StationID AS stationId, IFNULL(CAST(SUM(a.AddedToll)/100 as DECIMAL(10,2)) ,0) AS extAddToll, IFNULL(SUM(CASE WHEN a.payType=0 THEN a.AddedToll ELSE 0 END),0) as xjMoney, IFNULL(SUM(CASE WHEN a.payType=16 THEN a.AddedToll ELSE 0 END),0) as ydzfMoney FROM
SELECT * FROM ${tableName}
AND CancelFlag = 0 AND IsSplit=1 AND IsConfirm = 1 AND StationID in
#{stationId}
AND StaDate = #{timeFormat}
AND ShiftID = #{shiftId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
GROUP BY OperatorID

SELECT a.StaDate AS staDate, LEFT(a.StaDate, 6) AS monthDate, a.OperatorID AS operatorId, a.StationID AS stationId, IFNULL(CAST(SUM(a.AddedToll)/100 as DECIMAL(10,2)) ,0) AS extAddToll, IFNULL(SUM(CASE WHEN a.payType=0 THEN a.AddedToll ELSE 0 END),0) as xjMoney, IFNULL(SUM(CASE WHEN a.payType=16 THEN a.AddedToll ELSE 0 END),0) as ydzfMoney FROM
SELECT * FROM ${tableName}
AND CancelFlag = 0 AND IsSplit=1 AND IsConfirm = 1 AND StationID in
#{stationId}
AND StaDate = #{timeFormat}
AND ShiftID = #{shiftId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
GROUP BY OperatorID

SELECT a.TeamID AS teamId, a.OperatorID AS operatorId, (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID LIMIT 1 ) AS operatorName, IFNULL(SUM(CASE WHEN a.CardType=26 THEN 1 ELSE 0 END),0) AS yfIcCardNum, IFNULL(SUM(CASE WHEN a.CardType=254 THEN 1 ELSE 0 END),0) AS paperNum FROM tbrawentry a
AND a.CancelFlag = 0 AND a.RecordType&1=1 AND a.VehicleClass in(1,2,3,4,11,12,13,14,15,16,21,22,23,24,25,26) AND a.CardType IN (26,254)
AND a.StationID = #{stationId}
AND a.EntryDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
GROUP BY a.OperatorID

SELECT a.TeamID AS teamId, a.OperatorID AS operatorId, (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID LIMIT 1 ) AS operatorName, IFNULL(CAST(SUM(CASE WHEN a.DealStatus&14 IN (0,10) AND a.IdentifyStatus = 0 THEN a.Toll ELSE 0 END)/100 AS DECIMAL(10,2)),0) AS exitToll, IFNULL(SUM(CASE WHEN a.CardType=26 THEN 1 ELSE 0 END),0) AS yjIcCardNum, IFNULL(SUM(CASE WHEN a.CardType=254 THEN 1 ELSE 0 END),0) AS paperNum FROM tbrawexit a
AND a.CancelFlag=0 AND a.RecordType&3=3 AND a.RecordType&192=0 AND substring(a.LaneID,-4,1)=0 AND substring(a.LaneID,-3,1)=1
AND a.StationID = #{stationId}
AND a.ExitDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
GROUP BY a.OperatorID

SELECT a.OperatorID AS operatorId, (SELECT OperatorName FROM dbtoms.tboperatorinfo WHERE a.OperatorID = OperatorID LIMIT 1 ) AS operatorName, IFNULL(CAST(SUM(a.addedtoll) /100 AS DECIMAL(10, 2)) ,0) AS addedToll FROM ${tableName} a
AND a.CancelFlag=0 AND a.issplit=1 AND (a.paytype IS null OR a.paytype=0)
AND a.StationID = #{stationId}
AND a.StaDate = #{timeFormat}
AND a.ShiftID = #{shiftId}
GROUP BY a.operatorid

SELECT
StationID AS stationId,
IFNULL(CAST(sum(AddedToll)/100 as DECIMAL(10,2)), 0) AS addedToll,
IFNULL(CAST(sum(HandToll)/100 as DECIMAL(10,2)), 0) AS handToll
FROM ${tableName}

    AND CancelFlag = 0
    AND StationID in

        #{stationId}


        AND StaDate = #{timeFormat}


        AND ShiftID = #{shiftId}


GROUP BY StationID
ORDER BY StationID ASC

SELECT a.StationID AS stationId, (SELECT stationname FROM dbtoms.tbstationinfo WHERE a.StationID = stationid LIMIT 1 ) AS stationName, IFNULL(SUM(CASE WHEN a.DealStatus&14=6 THEN a.CarNum ELSE 0 END),0) AS officialIcCardCount, IFNULL(SUM(CASE WHEN a.DealStatus&14=8 THEN a.CarNum ELSE 0 END),0) AS militaryIcCardCount, IFNULL(SUM(CASE WHEN a.DealStatus&14=12 THEN a.CarNum ELSE 0 END),0) AS freeIcCardCount, IFNULL(SUM(CASE WHEN (a.DealStatus&14 != 14 AND a.DealStatus&14 != 2 AND a.DealStatus&0xE00000 != 0x200000 AND a.DealStatus&0x1000000=0 AND a.DealStatus&32 != 32 AND a.CardType=0) OR (a.CardType=26 AND a.DealStatus&32 != 32) THEN a.CardNum ELSE 0 END),0) AS dueIcCardCount, IFNULL(CAST(SUM(CASE WHEN PayType=0 THEN TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) douTotalToll, IFNULL(CAST(SUM(CASE WHEN a.DealStatus&14=4 THEN a.TotalArrearage ELSE 0 END)/100 AS DECIMAL(10,2)),0) arrearsAmount, IFNULL(CAST(SUM(CASE WHEN a.PayType = 0 THEN a.TotalToll ELSE 0 END)/ 100 AS DECIMAL(10,2)), 0) AS dueAmount, IFNULL(CAST(SUM(CASE WHEN a.PayType=16 THEN a.TotalToll ELSE 0 END)/100 as DECIMAL(10,2)), 0) mobilePaymentAmount, IFNULL(CAST(SUM(CASE WHEN a.PayType=2 THEN a.TotalToll ELSE 0 END) /100 as DECIMAL(10,2)), 0) as ePaymentAmount FROM ${tableName} a
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate = #{timeFormat}
AND ShiftID = #{shiftId}
GROUP BY StationID ORDER BY StationID ASC
